"using System.Collections.Generic;
using UnityEngine;
using UnityEngine.AI;

namespace SimuladorBloqueos
{
    /// <summary>
    /// Genera en tiempo de ejecución la NavMesh de toda la Base UTOP + Calle Junín a partir de los colliders
    /// de la escena (paredes, mesas, literas y muros quedan como obstáculos). Así los NPC rodean las
    /// paredes y el mobiliario en lugar de atravesarlos y evitan chocar entre sí.
    /// </summary>
    [DefaultExecutionOrder(-200)]
    public class RuntimeNavMeshBaker : MonoBehaviour
    {
        public static bool Ready { get; private set; }
        public Bounds area = new Bounds(new Vector3(18f, 3f, -4f), new Vector3(80f, 24f, 120f));
        private NavMeshData _data;
        private NavMeshDataInstance _instance;

        private void Awake()
        {
            Build();
        }

        public void Build()
        {
            if (Ready) return;
            NavMeshBuildSettings settings = NavMesh.GetSettingsByID(0);
            settings.agentRadius = 0.30f;
            settings.agentHeight = 1.80f;
            settings.agentClimb = 0.40f;
            settings.agentSlope = 48f;
            settings.minRegionArea = 0.5f;

            var markups = new List<NavMeshBuildMarkup>();
            var player = GameObject.FindGameObjectWithTag("Player");
            if (player != null)
                markups.Add(new NavMeshBuildMarkup { root = player.transform, ignoreFromBuild = true, overrideArea = false });
            foreach (var t in FindObjectsByType<NpcNavigator>())
