"using System.Collections.Generic;
using UnityEngine;
using UnityEngine.AI;

namespace SimuladorBloqueos
{
    /// <summary>
    /// Locomoción física de un NPC: NavMeshAgent (rodea paredes/mesas y esquiva a otros NPC) + CapsuleCollider
    /// kinemático (el jugador y otros objetos no pueden atravesarlo) + separación radial entre NPCs.
