        public int priority = 50;
        private Vector3 _fallbackTarget;
        private bool _fallbackMoving;
        private float _fallbackSpeed;
        private Vector3 _lastDest = new Vector3(float.MaxValue, 0f, 0f);

        public bool AgentActive => Agent != null && Agent.enabled && Agent.isOnNavMesh;
        public Vector3 Velocity => AgentActive ? Agent.velocity : (_fallbackMoving ? (_fallbackTarget - transform.position).normalized * _fallbackSpeed : Vector3.zero);

        private void OnEnable()
        {
            if (!AllNavigators.Contains(this)) AllNavigators.Add(this);
        }

        private void OnDisable()
        {
            AllNavigators.Remove(this);
        }

        private void Awake()
        {
            Body = GetComponent<CapsuleCollider>();
            if (Body == null) Body = gameObject.AddComponent<CapsuleCollider>();
            Body.direction = 1; Body.height = 1.75f; Body.radius = radius; Body.center = new Vector3(0f, 0.9f, 0f);
            var rb = GetComponent<Rigidbody>();
            if (rb == null) rb = gameObject.AddComponent<Rigidbody>();
            rb.isKinematic = true; rb.useGravity = false;
            priority = 30 + Random.Range(0, 40);
        }

        private void Start() { EnsureAgent(); }

