14:     /// </summary>
15:     public class ThirdPersonCamera : MonoBehaviour
16:     {
17:         [Header("Objetivo")]
18:         public Transform target;
19:         public Vector3 targetOffset = new Vector3(0, 1.35f, 0); // Altura de hombros/cabeza
20: 
21:         [Header("Distancia y Ángulos")]
22:         public float distance = 3.8f;
23:         public float minPitch = -25f;
24:         public float maxPitch = 65f;
25:         public float mouseSensitivityX = 1.6f;
26:         public float mouseSensitivityY = 1.3f;
27: 
28:         [Header("Suavizado")]
29:         public float smoothSpeed = 15f;
30: 
31:         private float _yaw = 0f;
32:         private float _pitch = 15f;
33: 
34:         private void Start()
35:         {
36:             Cursor.lockState = CursorLockMode.Locked;
37:             Cursor.visible = false;
38: 
39:             if (target != null)
40:             {
41:                 _yaw = target.eulerAngles.y;
42:             }
43:         }
44: 
45:         private void Update()
46:         {
47: #if ENABLE_INPUT_SYSTEM
48:             // Desbloqueo y bloqueo de cursor con New Input System
49:             if (Mouse.current != null && Mouse.current.leftButton.wasPressedThisFrame)
50:             {
51:                 Cursor.lockState = CursorLockMode.Locked;
52:                 Cursor.visible = false;
53:             }
54:             if (Keyboard.current != null && Keyboard.current.escapeKey.wasPressedThisFrame)
55:             {
56:                 Cursor.lockState = CursorLockMode.None;
57:                 Cursor.visible = true;
58:             }
59: 
60:             // Lectura del movimiento del ratón
61:             if (Mouse.current != null && Cursor.lockState == CursorLockMode.Locked)
62:             {
63:                 Vector2 delta = Mouse.current.delta.ReadValue();
64:                 _yaw += delta.x * 0.1f * mouseSensitivityX;
65:                 _pitch -= delta.y * 0.1f * mouseSensitivityY;
66:                 _pitch = Mathf.Clamp(_pitch, minPitch, maxPitch);
67:             }
68: #endif
69:         }
