71:         private void LateUpdate()
72:         {
73:             if (target == null) return;
74: 
75:             Vector3 focusPoint = target.position + targetOffset;
76:             Quaternion rotation = Quaternion.Euler(_pitch, _yaw, 0);
77:             Vector3 desiredPosition = focusPoint - (rotation * Vector3.forward * distance);
78: 
79:             // Suavizado de posición de cámara
80:             transform.position = Vector3.Lerp(transform.position, desiredPosition, Time.deltaTime * smoothSpeed);
